import{_ as a,c as t,o,ae as s}from"./chunks/framework.DEXG3EuZ.js";const h=JSON.parse('{"title":"Commerce Example","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/commerce.md","filePath":"en/guide/commerce.md","lastUpdated":1792605191000}'),n={name:"en/guide/commerce.md"};function i(r,e,c,d,l,p){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="commerce-example" tabindex="-1">Commerce Example <a class="header-anchor" href="#commerce-example" aria-label="Permalink to &quot;Commerce Example&quot;">​</a></h1><p>The store is a real server-state flow, not a button demo.</p><h2 id="routes" tabindex="-1">Routes <a class="header-anchor" href="#routes" aria-label="Permalink to &quot;Routes&quot;">​</a></h2><ul><li><code>/shop</code>: public catalog, keyword search, category filters, sorting, and infinite query.</li><li><code>/shop/products/:id</code>: localized detail, quantity, and a safe-area purchase bar.</li><li><code>/shop/admin/products</code>: authenticated admin search, create, edit, publication status, and soft deletion.</li></ul><p>Reusable product presentation and editing live in <code>src/components/shop</code>. Endpoints stay in <code>src/api/modules/products.ts</code>. TanStack Query owns cache, cancellation, mutations, and invalidation; product server state never enters Pinia.</p><h2 id="types-and-data" tabindex="-1">Types and data <a class="header-anchor" href="#types-and-data" aria-label="Permalink to &quot;Types and data&quot;">​</a></h2><p>Product contracts are generated from <code>openapi/schema.yaml</code>. Money is stored as integer cents and rendered with <code>Intl.NumberFormat</code>. Names, subtitles, and descriptions require <code>zh-CN</code>, <code>en-US</code>, and <code>ja-JP</code>, and the current locale selects the display value.</p><p>Cover images allow same-origin paths or HTTPS only and fall back to a local placeholder. Admin deletion is soft deletion and the public API exposes only <code>on_sale</code> products.</p><p><code>pnpm dev</code> uses <code>mock/index.ts</code>, so the full store works without Docker. <code>pnpm dev:integration</code> configures the Gin/FastAPI proxies. Review the contract differences below before using the full flow against these services.</p><h2 id="favorite-interaction" tabindex="-1">Favorite interaction <a class="header-anchor" href="#favorite-interaction" aria-label="Permalink to &quot;Favorite interaction&quot;">​</a></h2><p><code>FavoriteButton</code> receives a numeric <code>productId</code> and the current <code>session</code> token. Signed-out users see a login link; no private-state request is sent. A valid signed-in product loads its saved state before enabling the action. Failed reads offer retry. Failed writes preserve the last confirmed state and display an error. Fetching or saving disables duplicate submissions.</p><p>Favorite state belongs to TanStack Query. Cache keys include the control instance, session generation and product ID; they do not contain the token. A mutation captures its original cache key, so a late response cannot overwrite another account or product. Each new mount/session reads the server again. The action sets an explicit boolean rather than asking the server to invert unknown state.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  /api/product/favorite?id=1</span></span>
<span class="line"><span>POST /api/product/favorite</span></span>
<span class="line"><span>{ &quot;productId&quot;: 1, &quot;favorite&quot;: true }</span></span></code></pre></div><p><code>src/components/shop/FavoriteButton.vue</code> → <code>src/api/modules/favorites.ts</code> → <code>apiClient</code>.</p><p>Response-envelope compatibility does not adapt endpoint names or domain fields. This app’s catalog still uses <code>/api/products</code> and localized <code>name</code>/<code>priceCents</code>; the current Gin catalog exposes <code>/api/product/list</code> and <code>title</code>/<code>price</code>. Login also differs (<code>name</code>/<code>token</code> versus <code>username</code>/<code>accessToken</code>). Check the remaining contracts or add explicit domain adapters before claiming full integration. The new favorite paths match Gin; their authenticated use still requires a compatible issued JWT.</p><h2 id="detail-links-and-reused-pages" tabindex="-1">Detail links and reused pages <a class="header-anchor" href="#detail-links-and-reused-pages" aria-label="Permalink to &quot;Detail links and reused pages&quot;">​</a></h2><p>The detail page accepts only positive decimal integer IDs within JavaScript&#39;s safe integer range. Missing, repeated, negative, fractional, exponential or oversized IDs show an invalid-link message and a link back to the catalog without requesting a detail record.</p><p>Switching products in the same component resets quantity to 1 and clears the previous purchase feedback. A stock refresh clamps quantity to the available range; unavailable or unlisted products disable detail-page purchase and quantity controls. TanStack Query continues to own remote detail data and forwards <code>AbortSignal</code>; the cart does not become a second server cache.</p><p><a href="./request">API</a> · <a href="./testing">Tests</a></p>`,19)])])}const m=a(n,[["render",i]]);export{h as __pageData,m as default};
